import openpyxl
wb=openpyxl.load_workbook("documents/compliance-certificate-q3-2024.xlsx")
wv=openpyxl.load_workbook("documents/compliance-certificate-q3-2024.xlsx",data_only=True)
for ws in wb:
  print("=== ",ws.title, ws.dimensions)
  for row in ws.iter_rows():
    cells=[]
    for c in row:
      if c.value is not None:
        v=c.value; cv=wv[ws.title][c.coordinate].value
        cells.append(f"{c.coordinate}={v!r}"+(f" [{cv!r}]" if isinstance(v,str) and v.startswith("=") else ""))
    if cells: print(" | ".join(cells))
  if ws._comments if hasattr(ws,"_comments") else False: pass
EOF
